function layout({title,description,keyword='',path='/',body,schema=''}){ const url=`https://www.uzunelektro.nl${path}`; return `<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="index,follow"><link rel="canonical" href="${url}"><link rel="stylesheet" href="/site.css"><meta name="theme-color" content="#30323a"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:type" content="website">${schema}</head><body>${header()}<main>${body}</main>${footer()}<script src="/site.js" defer></script></body></html>`; }
