for (const s of services){
  const [slug,name,keyword,headline,intro,scope,button] = s;
  const faqItems = [
    [`Wanneer is ${name.toLowerCase()} nodig?`,`Dat hangt af van uw huidige installatie, het gewenste gebruik en eventuele toekomstige uitbreiding. We beoordelen de situatie voordat we een voorstel doen.`],
    [`Wat valt onder ${name.toLowerCase()}?`,`De werkzaamheden kunnen bestaan uit ${scope}. De definitieve omvang staat duidelijk in het voorstel.`],
    ['Kan ik foto’s meesturen?','Ja. Stuur via WhatsApp foto’s van de groepenkast, ruimte en bestaande installatie voor een betere eerste indruk.'],
    ['Hoe snel kan het worden uitgevoerd?','De planning hangt af van omvang, materiaal en actuele beschikbaarheid. We spreken een haalbaar moment met u af.']
  ];
  const links = slug.includes('laadpaal') ? [['/groepenkast-uitbreiden/','Groepenkast uitbreiden'],['/3-fase-aansluiting/','3-fase aansluiting']] : slug.includes('zonnepanelen') ? [['/groepenkast-uitbreiden/','Groepenkast'],['/thuisbatterij-installeren/','Thuisbatterij'],['/laadpaal-installeren/','Laadpaal']] : [['/diensten/','Alle diensten'],['/offerte-aanvragen/','Offerte aanvragen']];
  const message = `Goedendag, ik wil graag informatie over ${name.toLowerCase()}.`;
  const body = `<section class="page-hero">${crumbs([['/diensten/','Diensten']])}<p class="kicker">${esc(keyword.toUpperCase())}</p><h1>${headline}</h1><p>${intro}</p><div class="actions"><a class="btn" href="/offerte-aanvragen/?dienst=${slug}">${button}</a><a class="btn ghost" href="${wa(message)}" target="_blank" rel="noopener">WhatsApp ons</a></div></section><section class="section content-grid"><article><h2>Wat we voor u uitvoeren</h2><p>${intro}</p><p>Afhankelijk van de situatie verzorgen we ${scope}. We bekijken de bestaande installatie, bespreken het gewenste resultaat en stemmen de uitvoering af op uw woning, bedrijf of project.</p><h2>Zo pakken we het aan</h2><ol class="steps"><li><b>1</b><span><strong>Inventarisatie</strong>U deelt uw vraag, foto’s en locatie.</span></li><li><b>2</b><span><strong>Voorstel</strong>U krijgt een duidelijke omschrijving van de werkzaamheden.</span></li><li><b>3</b><span><strong>Uitvoering</strong>We plannen het werk en leveren het netjes op.</span></li></ol><div class="related"><h3>Ook relevant</h3>${links.map(([u,t])=>`<a href="${u}">${t} →</a>`).join('')}</div></article><aside class="quote-box"><h2>Uw situatie bespreken?</h2><p>Bel direct of stuur foto’s en uitleg via WhatsApp.</p><a class="btn" href="tel:${phone}">${phoneDisplay}</a><a href="${wa(message)}" target="_blank" rel="noopener">Open WhatsApp →</a></aside></section><section class="section muted"><div class="heading"><p class="kicker">VEELGESTELDE VRAGEN</p><h2>Vragen over ${name.toLowerCase()}</h2></div>${faq(faqItems)}</section>${cta(`Hulp nodig met ${name.toLowerCase()}?`,'Leg uw situatie kort aan ons voor.','Vraag een passend voorstel','/offerte-aanvragen/?dienst='+slug)}`;
  const serviceSchema = `<script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'Service','name':name,'provider':{'@type':'Electrician','name':'Uzun Elektrotechniek'},'areaServed':'Noord-Brabant','description':intro})}</script>`;
  files.set(`${slug}/index.html`,layout({title:`${name} in Noord-Brabant | Uzun Elektrotechniek`,description:`${intro} Vraag een duidelijke offerte aan bij Uzun Elektrotechniek in Noord-Brabant.`,keyword,path:`/${slug}/`,body,schema:serviceSchema}));
}

function simplePage(slug,title,kicker,intro,content,ctaBlock=cta()){ files.set(`${slug}/index.html`,layout({title:`${title} | Uzun Elektrotechniek`,description:intro,path:`/${slug}/`,body:`<section class="page-hero">${crumbs([])}<p class="kicker">${kicker}</p><h1>${title}</h1><p>${intro}</p></section><section class="section prose">${content}</section>${ctaBlock}`})); }

simplePage('particulier','Elektricien voor particulieren','WONING','Veilige en praktische elektrotechniek voor verbouwing, verduurzaming en dagelijks wooncomfort.',`<h2>Klein werk en complete woninginstallaties</h2><p>Een extra stopcontact, nieuwe groep, laadpaal of volledige renovatie: iedere woning vraagt om een oplossing die past bij gebruik en toekomstplannen.</p>${cards(['groepenkast-vervangen','stopcontact-aanleggen','elektrische-installatie-woning','laadpaal-installeren','zonnepanelen-aansluiten','domotica'])}<h2>Wanneer neemt u contact op?</h2><p>Bij verbouwing, een nieuwe keuken, overstap naar elektrisch koken, verduurzaming of twijfel over de bestaande installatie denken we graag mee.</p>`);
simplePage('zakelijk','Zakelijke elektrotechniek','BEDRIJF','Installaties, verlichting, data en beveiliging voor winkels, horeca, kantoren, magazijnen en werkplaatsen.',`<h2>Eén aanspreekpunt voor techniek</h2><p>We stemmen werkzaamheden af op bedrijfsvoering, planning en andere partijen. Zowel gerichte aanpassingen als grotere renovatie- en nieuwbouwprojecten zijn bespreekbaar.</p>${cards(['elektrische-installatie-bedrijfspand','krachtstroom-aanleggen','bedrijfsverlichting','noodverlichting','netwerkbekabeling','camerabeveiliging'])}<h2>Zakelijke aanvraag indienen</h2>${form('zakelijk')}`,cta('Een zakelijk project bespreken?','Deel locatie, planning en gewenste werkzaamheden.','Zakelijke aanvraag','/offerte-aanvragen/?type=zakelijk'));
simplePage('over-ons','Over Uzun Elektrotechniek','OVER ONS','Persoonlijk contact en zorgvuldig elektrotechnisch werk voor klanten in Noord-Brabant.',`<h2>Techniek zonder onduidelijkheid</h2><p>Uzun Elektrotechniek, handelend onder de naam Uzun Elektro, helpt particulieren en bedrijven met aanpassingen, uitbreidingen en complete installaties. We bespreken vooraf wat nodig is, lossen herstelpunten op en meten en controleren de installatie vóór oplevering.</p><h2>Bedrijfsgegevens</h2><dl><dt>Officiële bedrijfsnaam</dt><dd>Uzun Elektrotechniek</dd><dt>Handelsnaam</dt><dd>Uzun Elektro</dd><dt>Vestigingsadres</dt><dd>${address} — geen bezoekadres</dd><dt>KvK-nummer</dt><dd>82600678</dd><dt>BTW-identificatienummer</dt><dd>NL003705240B58</dd><dt>Werkgebied</dt><dd>Heel Noord-Brabant</dd></dl>`);
simplePage('werkgebied','Werkgebied Noord-Brabant','REGIO','Uzun Elektrotechniek voert werkzaamheden uit in heel Noord-Brabant.',`<h2>Elektricien in uw regio</h2><p>We werken onder meer in Drunen, Den Bosch, Waalwijk, Tilburg, Breda, Eindhoven, Oisterwijk, Vught, Heusden, Kaatsheuvel en omliggende plaatsen. Voor grotere projecten bespreken we de locatie en planning vooraf.</p><div class="location-grid">${['Drunen en Heusden','Den Bosch en Vught','Waalwijk en Kaatsheuvel','Tilburg en Oisterwijk','Breda en omgeving','Eindhoven en omgeving'].map(x=>`<span>${x}</span>`).join('')}</div><h2>Kleine klus of groter project</h2><p>Zowel particulieren als bedrijven, aannemers, VvE’s en vastgoedbeheerders kunnen een aanvraag indienen.</p>`);
simplePage('contact','Contact','CONTACT','Neem contact op met Uzun Elektrotechniek voor werkzaamheden in heel Noord-Brabant.',`<div class="content-grid"><div><h2>Direct contact</h2><a class="phone-large" href="tel:${phone}">${phoneDisplay}</a><a class="phone-second" href="tel:${phone2}">${phone2Display}</a><a href="mailto:${email}">${email}</a><a class="btn" href="${wa('Goedendag, ik wil graag contact met Uzun Elektrotechniek.')}" target="_blank" rel="noopener">WhatsApp ons</a><dl><dt>Vestigingsadres</dt><dd>${address}<br><strong>Geen bezoekadres; uitsluitend op afspraak</strong></dd><dt>Openingstijden</dt><dd>Maandag t/m vrijdag 08:00–18:00 uur<br>Avond en zaterdag op afspraak</dd><dt>Reactietijd</dt><dd>Binnen één werkdag</dd></dl></div>${form('contact')}</div>`, '');
simplePage('storing-melden','Elektrische storing melden','STORING','Meld een elektrische storing voor beoordeling en planning tijdens onze bereikbaarheid.',`<div class="notice"><strong>Geen 24-uurs storingsdienst</strong><p>Bij direct gevaar, brandlucht of vonken: schakel de installatie alleen uit als dit veilig kan en bel bij brand of acuut gevaar 112.</p></div>${form('storing')}`,cta('Wilt u de storing telefonisch toelichten?','Bel tijdens onze bereikbaarheid.','Bel '+phoneDisplay,`tel:${phone}`));

const allFaq = [...commonFaq,
 ['Wanneer moet een groepenkast worden vervangen?','Bij veroudering, onvoldoende capaciteit, schade of een grote uitbreiding kan vervanging verstandig zijn. Laat de bestaande situatie eerst beoordelen.'],
 ['Wanneer is 3-fase nodig?','Dat hangt af van het totale vermogen en apparatuur zoals inductie, laadpaal of machines. De netaansluiting en groepenkast moeten beide passend zijn.'],
 ['Heeft een laadpaal een aparte groep nodig?','Doorgaans wel. Ook load balancing kan nodig zijn om overbelasting van de hoofdaansluiting te voorkomen.'],
 ['Waarom valt mijn aardlekschakelaar uit?','Dat kan door een defect apparaat, vocht, bekabelingsprobleem of fout in de installatie komen. Blijft het probleem terugkomen, laat het onderzoeken.'],
 ['Kan een laadpaal samenwerken met zonnepanelen?','Ja, afhankelijk van laadpaal, energiemeter en regeling kan laden op eigen zonnestroom worden ondersteund.'],
 ['Wat is het verschil tussen CAT6 en CAT7?','De keuze hangt af van snelheid, afstand, omgeving en gewenste toekomstbestendigheid. Een correcte aanleg en afwerking zijn minstens zo belangrijk.']
];
