function form(type){
 const common = `<div class="form-grid"><label>Voornaam<input name="voornaam" autocomplete="given-name" required></label><label>Achternaam<input name="achternaam" autocomplete="family-name" required></label><label>Bedrijfsnaam<input name="bedrijf" autocomplete="organization"></label><label>E-mailadres<input type="email" name="email" autocomplete="email" required></label><label>Telefoonnummer<input type="tel" name="telefoon" autocomplete="tel" required></label><label>Postcode<input name="postcode" autocomplete="postal-code" required></label><label>Huisnummer<input name="huisnummer" required></label><label>Toevoeging<input name="toevoeging"></label><label>Plaats<input name="plaats" autocomplete="address-level2" required></label></div>`;
 const open = `<form class="lead-form" data-form="${type}" action="/api/submit.php" method="post" enctype="multipart/form-data"><input type="hidden" name="formulier" value="${type}"><div class="hp" aria-hidden="true"><label>Niet invullen<input name="website" tabindex="-1" autocomplete="off"></label></div>`;
 const actions = `<div class="form-actions"><button class="btn" type="submit">Aanvraag per e-mail versturen</button><button class="btn whatsapp-submit" type="button">Aanvraag via WhatsApp</button></div><p class="form-status" aria-live="polite">Na e-mailverzending ontvangt u automatisch een bevestiging. Reactie binnen één werkdag.</p></form>`;
 if(type==='storing') return `${open}<label>Naam<input name="naam" required></label><div class="form-grid"><label>E-mailadres<input type="email" name="email"></label><label>Telefoonnummer<input type="tel" name="telefoon" required></label><label>Postcode<input name="postcode" required></label><label>Plaats<input name="plaats" required></label></div><label>Type storing<select name="storing" required><option value="">Kies een storing</option>${['Geen stroom','Groep valt uit','Aardlekschakelaar valt uit','Kortsluiting','Stopcontact werkt niet','Verlichting werkt niet','Groepenkastprobleem','Anders'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Korte omschrijving<textarea name="omschrijving" rows="5" required></textarea></label><label>Foto of document<input type="file" name="bijlagen[]" multiple accept="image/jpeg,image/png,image/webp,application/pdf"><small>Maximaal 5 bestanden; JPG, PNG, WebP of PDF.</small></label>${actions}`;
 if(type==='terugbellen') return `${open}<div class="form-grid"><label>Naam<input name="naam" required></label><label>Telefoonnummer<input type="tel" name="telefoon" required></label><label>E-mailadres<input type="email" name="email"></label><label>Gewenste dag/tijd<input name="gewenste_tijd" required></label></div><label>Onderwerp<textarea name="omschrijving" rows="4" required></textarea></label><label class="consent"><input type="checkbox" required>Ik ga akkoord met de <a href="/privacy/">privacyverklaring</a>.</label>${actions}`;
 if(type==='afspraak') return `${open}${common}<label>Gewenste dag/tijd<input name="gewenste_tijd" required></label><label>Werkzaamheden<textarea name="omschrijving" rows="5" required></textarea></label><label>Foto of document<input type="file" name="bijlagen[]" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></label><label class="consent"><input type="checkbox" required>Ik ga akkoord met de <a href="/privacy/">privacyverklaring</a>.</label>${actions}`;
 return `${open}${common}<label>Type klant<select name="klanttype" required><option value="">Maak een keuze</option>${['Particulier','Zakelijk','VvE','Aannemer','Vastgoedbeheerder','Anders'].map(x=>`<option>${x}</option>`).join('')}</select></label><fieldset><legend>Werkzaamheden</legend><div class="checks">${['Groepenkast','Meterkast','Nieuwe groep','Krachtstroom','Stopcontacten','Verlichting','Storing of herstel','Laadpaal','Zonnepanelen elektrisch aansluiten','Thuisbatterij','Camerabeveiliging','Netwerk','Intercom / toegangscontrole','Domotica / Tuya / Alexa','Complete elektrische installatie','Anders'].map(x=>`<label><input type="checkbox" name="werkzaamheden[]" value="${x}">${x}</label>`).join('')}</div></fieldset><label>Omschrijving<textarea name="omschrijving" rows="6" required placeholder="Beschrijf zo duidelijk mogelijk welke werkzaamheden u wilt laten uitvoeren."></textarea></label><label>Foto’s of documenten<input type="file" name="bijlagen[]" multiple accept="image/jpeg,image/png,image/webp,application/pdf"><small>Maximaal 5 bestanden; JPG, PNG, WebP of PDF. U kunt deze ook via WhatsApp sturen.</small></label><label>Gewenste uitvoering<select name="planning"><option>Zo snel mogelijk</option><option>Binnen 1 week</option><option>Binnen 1 maand</option><option>Binnen 3 maanden</option><option>Nog niet bekend</option></select></label><fieldset><legend>Contactvoorkeur</legend><div class="radio"><label><input type="radio" name="contactvoorkeur" value="Telefonisch" checked>Telefonisch</label><label><input type="radio" name="contactvoorkeur" value="E-mail">E-mail</label><label><input type="radio" name="contactvoorkeur" value="WhatsApp">WhatsApp</label></div></fieldset><label class="consent"><input type="checkbox" required>Ik ga akkoord met de <a href="/privacy/">privacyverklaring</a>.</label>${actions}`;
}

