const legal = {
 'privacy':['Privacyverklaring','Deze pagina beschrijft welke persoonsgegevens via de website worden gevraagd en met welk doel.',`<h2>Welke gegevens wij verwerken</h2><p>Via formulieren kunnen naam, contactgegevens, adres, aanvraaginformatie en meegestuurde foto’s of documenten worden verwerkt. Wij gebruiken deze gegevens uitsluitend om contact op te nemen, de aanvraag te beoordelen, een afspraak te plannen en een offerte of opdracht uit te voeren.</p><h2>Bewaartermijn</h2><p>Aanvragen en bijlagen worden maximaal twee jaar bewaard, tenzij een wettelijke bewaarplicht of lopende overeenkomst een andere termijn vereist.</p><h2>Uw rechten</h2><p>Voor inzage, correctie of verwijdering kunt u contact opnemen met privacycontactpersoon Can Uzun via <a href="mailto:${email}">${email}</a>.</p><h2>Delen en beveiliging</h2><p>Gegevens worden niet voor marketingdoeleinden verkocht. Alleen partijen die noodzakelijk zijn voor communicatie, hosting of uitvoering kunnen gegevens verwerken volgens toepasselijke afspraken.</p>`],
 'cookiebeleid':['Cookiebeleid','Informatie over cookies en vergelijkbare technieken op deze website.',`<h2>Huidige situatie</h2><p>De website gebruikt momenteel geen marketingcookies en plaatst geen analysecookies. Wanneer Google Analytics of andere meetdiensten worden toegevoegd, wordt dit beleid bijgewerkt en wordt waar nodig toestemming gevraagd.</p>`],
 'algemene-voorwaarden':['Algemene voorwaarden','Voorwaarden voor offertes en werkzaamheden van Uzun Elektrotechniek.',`<h2>Nog invullen</h2><p>De definitieve algemene voorwaarden zijn nog niet aangeleverd. Publiceer hier de voorwaarden die daadwerkelijk op offertes en opdrachten van toepassing zijn.</p>`],
 'disclaimer':['Disclaimer','Toelichting op de informatie op deze website.',`<h2>Algemene informatie</h2><p>De website geeft algemene informatie over mogelijke werkzaamheden. Een definitieve technische beoordeling, prijs, planning en omvang volgen pas na inventarisatie en bevestiging in een offerte of opdracht.</p>`]
};
for(const [slug,[title,desc,content]] of Object.entries(legal)) simplePage(slug,title,'JURIDISCH',desc,content,'');

const css = `@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=Manrope:wght@400;500;600;700&display=swap');
:root{--ink:#30323a;--ink2:#202126;--gold:#dfb63e;--gold2:#bc9020;--paper:#fff;--soft:#f3f3f4;--muted:#666a73;--line:#d9dadd;--green:#16883f}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);font:16px/1.65 Manrope,Arial,sans-serif;background:var(--paper)}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto}h1,h2,h3{font-family:"Barlow Condensed",sans-serif;line-height:.98;margin:0 0 20px;text-transform:uppercase}h1{font-size:clamp(3.4rem,7vw,7rem)}h2{font-size:clamp(2.4rem,4.5vw,4.6rem)}h3{font-size:1.7rem}p{margin:0 0 20px}.site-header{height:94px;padding:0 clamp(20px,6vw,96px);display:flex;align-items:center;gap:36px;border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(255,255,255,.96);backdrop-filter:blur(10px);z-index:20}.logo{margin-right:auto}.logo img{display:block;width:260px}.site-header nav{display:flex;gap:25px;font-size:.86rem;font-weight:700}.site-header nav a:hover{color:var(--gold2)}.menu{display:none}.btn{display:inline-flex;justify-content:center;align-items:center;padding:15px 21px;background:var(--gold);color:var(--ink2);font-weight:800;border:0;cursor:pointer;min-height:52px}.btn:hover{background:var(--gold2)}.btn.small{padding:11px 16px;min-height:44px;font-size:.82rem}.btn.ghost{background:transparent;border:1px solid currentColor}.btn.dark{background:var(--ink2);color:#fff}.kicker{font-size:.75rem;letter-spacing:.17em;font-weight:800;color:var(--gold2);margin-bottom:18px}.hero{min-height:680px;padding:clamp(60px,9vw,125px) clamp(24px,7vw,108px);display:grid;grid-template-columns:1.3fr .7fr;gap:8vw;align-items:center;background:linear-gradient(125deg,#f7f7f8 0 68%,#30323a 68%)}.hero>div>p:not(.kicker){font-size:1.18rem;max-width:760px}.hero h1 em{color:var(--gold2);font-style:normal}.hero aside{background:var(--ink2);color:#fff;padding:38px;border-top:5px solid var(--gold);display:flex;flex-direction:column;gap:12px}.hero aside span{font-size:.7rem;letter-spacing:.15em}.hero aside strong{font:700 2.2rem "Barlow Condensed"}.hero aside a{color:var(--gold)}.actions{display:flex;gap:14px;flex-wrap:wrap;margin:28px 0}.ticks{display:flex;gap:22px;flex-wrap:wrap;padding:0;margin:42px 0 0;list-style:none;font-size:.82rem;font-weight:700}.ticks li:before{content:'✓';color:var(--gold2);margin-right:7px}.section{padding:100px clamp(24px,7vw,108px)}.section.muted{background:var(--soft)}.heading{max-width:800px;margin-bottom:46px}.cards{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);margin-bottom:32px}.cards article{padding:28px 24px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);min-height:270px}.cards article:nth-child(4n){border-right:0}.cards article p{color:var(--muted);font-size:.9rem}.cards article>a,.text-link,.duo article>a,.related a{font-weight:800;color:var(--gold2)}.card-icon{display:block;color:var(--gold2);margin-bottom:30px}.split{padding:100px clamp(24px,7vw,108px);display:grid;grid-template-columns:1fr 1fr;gap:10vw}.dark{background:var(--ink2);color:#fff}.benefits{list-style:none;margin:0;padding:0}.benefits li{display:grid;gap:4px;padding:19px 0;border-bottom:1px solid #44464e}.benefits span{color:#b7b9bf}.duo{display:grid;grid-template-columns:1fr 1fr;gap:2px;padding-block:2px}.duo article{padding:75px;background:var(--soft)}.duo article:nth-child(2){background:var(--gold)}.empty{border:1px dashed #aeb0b5;background:#fafafa;padding:40px;display:flex;flex-direction:column;gap:10px}.cta{background:var(--gold);padding:70px clamp(24px,7vw,108px);display:flex;justify-content:space-between;align-items:center;gap:40px}.cta>div{max-width:730px}.cta h2{font-size:clamp(2.6rem,5vw,5.2rem)}.page-hero{padding:75px clamp(24px,7vw,108px) 90px;background:var(--soft)}.page-hero>p:not(.kicker){font-size:1.12rem;max-width:790px}.page-hero.compact{padding-bottom:60px}.page-hero.center{text-align:center;min-height:65vh;display:flex;flex-direction:column;align-items:center;justify-content:center}.crumbs{display:flex;gap:9px;font-size:.75rem;color:var(--muted);margin-bottom:35px}.content-grid{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:9vw}.content-grid article>p{max-width:770px}.steps{padding:0;list-style:none}.steps li{display:flex;gap:18px;padding:18px 0;border-bottom:1px solid var(--line)}.steps li>b{font-family:"Barlow Condensed";color:var(--gold2)}.steps li span{display:grid}.quote-box{background:var(--ink2);color:#fff;padding:32px;height:max-content;position:sticky;top:125px}.quote-box .btn{display:flex;margin:24px 0 18px}.related{margin-top:45px;display:flex;gap:20px;flex-wrap:wrap}.related h3{width:100%}.faq{max-width:900px}.faq details{border-bottom:1px solid var(--line)}.faq summary{padding:22px 0;font-weight:800;cursor:pointer;list-style:none}.faq summary:after{content:'+';float:right;color:var(--gold2);font-size:1.4rem}.faq details[open] summary:after{content:'–'}.faq details p{color:var(--muted);padding:0 36px 22px 0}.service-groups>div{margin-bottom:75px}.prose{max-width:1200px}.prose>p,.prose>h2,.prose>dl{max-width:820px}.prose dl,dl{display:grid;grid-template-columns:190px 1fr;gap:0;margin:30px 0}.prose dt,.prose dd,dt,dd{padding:12px 0;border-bottom:1px solid var(--line);margin:0}.prose dt,dt{font-weight:800}.location-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);margin:35px 0 60px}.location-grid span{background:#fff;padding:25px;font-weight:700}.phone-large{display:block;font:800 2.6rem "Barlow Condensed";margin-bottom:25px}.notice{background:#fff5d7;border-left:5px solid var(--gold);padding:24px;margin-bottom:30px}.form-section{padding-top:50px}.lead-form{max-width:1000px;background:#fff;padding:clamp(24px,5vw,55px);box-shadow:0 18px 60px rgba(35,36,42,.1);border-top:5px solid var(--gold)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.lead-form label,.lead-form legend{display:block;font-size:.84rem;font-weight:800;margin-bottom:18px}.lead-form input,.lead-form select,.lead-form textarea{display:block;width:100%;font:inherit;padding:13px 12px;border:1px solid #bfc1c6;margin-top:7px;background:#fff}.lead-form textarea{resize:vertical}.lead-form input:focus,.lead-form select:focus,.lead-form textarea:focus{outline:3px solid rgba(223,182,62,.3);border-color:var(--gold2)}fieldset{border:0;padding:0;margin:18px 0}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.checks label,.radio label,.consent{font-weight:500;margin:0;display:flex;gap:8px;align-items:flex-start}.checks input,.radio input,.consent input{width:auto;margin:5px 0 0}.radio{display:flex;gap:24px;flex-wrap:wrap}.lead-form small{display:block;color:var(--muted);font-weight:400;margin-top:5px}.lead-form .btn{margin-top:26px}.form-status{font-size:.8rem;color:var(--muted);margin-top:12px}.hp{position:absolute;left:-10000px}.footer-grid{padding:70px clamp(24px,7vw,108px);background:#24262c;color:#fff;display:grid;grid-template-columns:1.5fr repeat(3,1fr);gap:50px}.footer-grid>div{display:flex;flex-direction:column;gap:10px}.footer-grid img{width:255px;margin-bottom:10px}.footer-grid p,.footer-grid span{color:#b6b8be;font-size:.82rem}.footer-grid h3{font-size:1.2rem}.copyright{background:#1b1c20;color:#92949a;padding:18px clamp(24px,7vw,108px);font-size:.75rem}.mobile-bar{display:none}
@media(max-width:1000px){.site-header nav{display:none}.menu{display:block;background:transparent;border:1px solid var(--line);padding:9px 12px}.site-header.open nav{display:flex;position:absolute;top:94px;left:0;right:0;background:#fff;padding:24px;flex-direction:column;border-bottom:1px solid var(--line)}.cards{grid-template-columns:repeat(2,1fr)}.cards article:nth-child(2n){border-right:0}.hero{grid-template-columns:1fr;background:var(--soft)}.hero aside{max-width:500px}.content-grid{grid-template-columns:1fr}.quote-box{position:static}.footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:650px){body{padding-bottom:62px}h1{font-size:3.35rem}.site-header{height:76px;padding:0 18px}.logo img{width:190px}.site-header>.btn{display:none}.site-header.open nav{top:76px}.hero,.section,.split,.page-hero{padding:62px 20px}.hero{min-height:auto}.hero aside{padding:25px}.ticks{display:grid;gap:8px}.cards,.duo,.split,.form-grid,.checks,.location-grid,.footer-grid{grid-template-columns:1fr}.cards article{border-right:0;min-height:auto}.duo article{padding:55px 24px}.cta{padding:52px 20px;display:block}.cta .btn{margin-top:15px}.content-grid{display:block}.quote-box{margin-top:40px}.lead-form{padding:24px 18px}.prose dl,dl{grid-template-columns:1fr}.prose dd,dd{padding-top:0}.footer-grid{padding:55px 20px}.mobile-bar{display:grid;grid-template-columns:repeat(3,1fr);position:fixed;bottom:0;left:0;right:0;z-index:30;background:var(--ink2);color:#fff;box-shadow:0 -4px 18px rgba(0,0,0,.2)}.mobile-bar a{text-align:center;padding:18px 6px;font-size:.8rem;font-weight:800}.mobile-bar a:nth-child(2){background:var(--green)}.mobile-bar a:nth-child(3){background:var(--gold);color:var(--ink2)}}`;

const js = `const header=document.querySelector('.site-header');const menu=document.querySelector('.menu');if(menu){menu.addEventListener('click',()=>{const open=header.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});}document.querySelectorAll('.lead-form').forEach(form=>{const button=form.querySelector('.whatsapp-submit');if(!button)return;button.addEventListener('click',()=>{if(!form.reportValidity())return;if(form.elements.website?.value)return;const data=new FormData(form);const lines=['Goedendag, ik wil via de website een aanvraag indienen.'];const labels={formulier:'Type aanvraag',voornaam:'Voornaam',achternaam:'Achternaam',naam:'Naam',bedrijf:'Bedrijf',email:'E-mail',telefoon:'Telefoon',postcode:'Postcode',huisnummer:'Huisnummer',toevoeging:'Toevoeging',plaats:'Plaats',klanttype:'Type klant','werkzaamheden[]':'Werkzaamheden',omschrijving:'Omschrijving',planning:'Planning',contactvoorkeur:'Contactvoorkeur',storing:'Type storing',gewenste_tijd:'Gewenst moment'};for(const [key,value] of data.entries()){if(key==='website'||value instanceof File||!String(value).trim())continue;lines.push((labels[key]||key)+': '+value);}lines.push('Foto’s of documenten stuur ik eventueel in dit WhatsApp-gesprek.');form.querySelector('.form-status').textContent='WhatsApp wordt geopend. Controleer het bericht en druk daar op verzenden.';window.open('https://wa.me/${whatsapp}?text='+encodeURIComponent(lines.join('\\n')),'_blank','noopener');});});`;

const php = String.raw`<?php
declare(strict_types=1);
session_start();
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); exit('Alleen POST toegestaan.'); }
if (!empty($_POST['website'] ?? '')) { header('Location: /bedankt/'); exit; }
if (isset($_SESSION['last_submit']) && time() - (int)$_SESSION['last_submit'] < 20) { http_response_code(429); exit('Wacht even voordat u opnieuw verzendt.'); }
$_SESSION['last_submit'] = time();

$recipient = 'info@uzunelektro.nl';
$allowed = ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];
$fields = [];
foreach ($_POST as $key => $value) {
  if ($key === 'website') continue;
  $label = preg_replace('/[^a-zA-Z0-9_\-]/', '', (string)$key);
  if (is_array($value)) $value = implode(', ', array_map('strip_tags', $value));
  $fields[] = $label . ': ' . trim(strip_tags((string)$value));
}
$emailValue = filter_var($_POST['email'] ?? '', FILTER_VALIDATE_EMAIL) ?: '';
$name = trim(strip_tags((string)($_POST['naam'] ?? (($_POST['voornaam'] ?? '') . ' ' . ($_POST['achternaam'] ?? '')))));
$formType = preg_replace('/[^a-z0-9 -]/i', '', trim((string)($_POST['formulier'] ?? 'website')));
$subject = 'Nieuwe ' . $formType . ' - Uzun Elektro website';
$boundary = 'uzun-' . bin2hex(random_bytes(12));
$body = '--' . $boundary . "\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: 8bit\r\n\r\n" . implode("\r\n", $fields) . "\r\n";
$files = $_FILES['bijlagen'] ?? null;
if ($files && is_array($files['name'])) {
  $count = min(count($files['name']), 5); $total = 0; $finfo = new finfo(FILEINFO_MIME_TYPE);
  for ($i=0; $i<$count; $i++) {
    if (($files['error'][$i] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) continue;
    if (($files['error'][$i] ?? 1) !== UPLOAD_ERR_OK) { http_response_code(400); exit('Een bestand kon niet worden ontvangen.'); }
    $size = (int)$files['size'][$i]; $total += $size;
    if ($size > 8 * 1024 * 1024 || $total > 20 * 1024 * 1024) { http_response_code(413); exit('De bestanden zijn te groot.'); }
    $mime = $finfo->file($files['tmp_name'][$i]);
    if (!isset($allowed[$mime])) { http_response_code(415); exit('Dit bestandstype is niet toegestaan.'); }
    $filename = 'bijlage-' . ($i + 1) . '.' . $allowed[$mime];
    $data = chunk_split(base64_encode((string)file_get_contents($files['tmp_name'][$i])));
    $body .= '--' . $boundary . "\r\nContent-Type: " . $mime . "; name=\"" . $filename . "\"\r\nContent-Disposition: attachment; filename=\"" . $filename . "\"\r\nContent-Transfer-Encoding: base64\r\n\r\n" . $data . "\r\n";
  }
}
$body .= '--' . $boundary . "--\r\n";
$headers = "From: Uzun Elektro website <noreply@uzunelektro.nl>\r\nMIME-Version: 1.0\r\nContent-Type: multipart/mixed; boundary=\"" . $boundary . "\"";
if ($emailValue) $headers .= "\r\nReply-To: " . $emailValue;
$sent = mail($recipient, $subject, $body, $headers);
if (!$sent) { http_response_code(500); exit('Verzenden is niet gelukt. Bel of WhatsApp ons via 06 13 27 12 61.'); }
if ($emailValue) {
  $confirmSubject = 'Ontvangstbevestiging Uzun Elektro';
  $confirmBody = "Beste " . ($name ?: 'klant') . ",\n\nBedankt voor uw aanvraag. Wij hebben uw gegevens ontvangen en reageren binnen één werkdag.\n\nMet vriendelijke groet,\nUzun Elektro\n06 13 27 12 61\ninfo@uzunelektro.nl";
  $confirmHeaders = "From: Uzun Elektro <info@uzunelektro.nl>\r\nContent-Type: text/plain; charset=UTF-8";
  mail($emailValue, $confirmSubject, $confirmBody, $confirmHeaders);
}
header('Location: /bedankt/');
exit;
?>`;

files.set('site.css',css + `.form-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.whatsapp-submit{background:var(--green);color:#fff}.phone-second{display:block;font:700 1.65rem "Barlow Condensed";margin:-18px 0 12px}.footer-grid strong{color:#fff;font-size:.78rem}@media(max-width:650px){.form-actions{display:grid}.form-actions .btn{width:100%}}`); files.set('site.js',js); files.set('api/submit.php',php);
files.set('robots.txt','User-agent: *\nAllow: /\nSitemap: https://www.uzunelektro.nl/sitemap.xml\n');
const urls=['/',...Array.from(files.keys()).filter(x=>x.endsWith('/index.html')).map(x=>'/'+x.replace('index.html',''))];
files.set('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(u=>`<url><loc>https://www.uzunelektro.nl${u}</loc></url>`).join('')}</urlset>`);

for (const stale of ['nen-1010-inspectie','nen-3140-inspectie','keuringen-inspecties','alarmsysteem','projecten','zonnepanelen']) {
  await rm(new URL(`${stale}/`, out), { recursive: true, force: true });
}
for (const staleFile of ['styles.css','script.js','brand.css']) {
  await rm(new URL(staleFile, out), { force: true });
}
for(const [name,content] of files){
  const target=new URL(name,out);
  await mkdir(new URL('./',target),{recursive:true});
  const cleaned = typeof content === 'string' ? content
    .replace(/<footer>[\s\S]*?<\/footer><div class="mobile-bar">[\s\S]*?<\/div>/, businessFooter())
    .replace('<a href="/projecten/">Projecten</a>','')
    .replace('Persoonlijk contact</li>','Reactie binnen één werkdag</li>')
    .replace('We plannen het werk en leveren het netjes op.','We voeren het werk uit, lossen herstelpunten op en meten en controleren vóór oplevering.')
    .replace('<a href="/keuringen-inspecties/">Inspecties</a>','<a href="/elektrische-storing/">Storing &amp; herstel</a>')
    .replace('<label><input type="checkbox" name="werkzaamheden" value="Keuring / inspectie">Keuring / inspectie</label>','') : content;
  await writeFile(target,cleaned);
}
console.log(`Built ${files.size} files`);
